const app=document.querySelector('#app');
const esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const link=(u,t,c='')=>`<a class="${c}" href="${u}" target="_blank" rel="noreferrer">${t} ↗</a>`;
function setView(v){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v)); app.innerHTML=v==='days'?days():v==='gallery'?gallery():v==='prep'?prep():sources(); scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));
function dayNav(){return `<div class="daynav">${D.map((d,i)=>`<a href="#d${i}"><b>${i+1}</b><span>${d.date}</span></a>`).join('')}</div>`}
function days(){return `<section class="hero"><img src="${IMG['cover.png']}" alt="המחשה עריכתית של טוקיו בנובמבר"><div><span>13–19 בנובמבר 2026 · בסיס בשיבויה</span><h1>טוקיו, יום אחרי יום</h1><p>שישה ימי טיול מאוזנים לפי אזורים, ועוד בוקר יציאה גמיש. מספיק כיוון כדי לא לבזבז זמן, בלי להפוך את החופשה ללוח זמנים קשיח.</p></div></section>${dayNav()}<section class="overview"><h2>התוכנית במבט אחד</h2><div>${D.map((d,i)=>`<a href="#d${i}"><i>${String(i+1).padStart(2,'0')}</i><small>${d.date}</small><b>${d.area}</b><span>${d.tag}</span></a>`).join('')}</div></section>${D.map(day).join('')}`}
function day(d,i){return `<article class="day" id="d${i}"><header><div class="num">${String(i+1).padStart(2,'0')}</div><div><small>${d.date}</small><h2>${d.area}</h2><span>${d.tag}</span></div></header><p class="lead">${d.intro}</p>${i===1?`<figure class="map"><figcaption><span>בוקר ברגל בהרג׳וקו ובאומוטסנדו; אחר הצהריים ברכבת לנקאנו. המפה הישנה הוסרה כדי שלא תציג את שיבויה סקיי.</span>${link(dayRoutes[i],'מסלול הבוקר')}${link("https://www.google.com/maps/dir/?api=1&destination=5-ch%C5%8Dme-50-3+Nakano%2C+Nakano+City%2C+Tokyo+164-0001%2C+Japan&destination_place_id=ChIJY5mZ55nyGGARFr9LsKUL6mI&origin=5-ch%C5%8Dme-52-15+Nakano%2C+Nakano+City%2C+Tokyo+164-0001%2C+Japan&origin_place_id=ChIJg-7dspDyGGARvvDv4E5-tuE&travelmode=walking",'מ־Broadway למגורו מארט')}</figcaption></figure>`:`<figure class="map"><img src="${IMG[dayMaps[i]]}" alt="מפת יום ${i+1}: ${esc(d.area)}"><figcaption><span>${i===0?'מפת היום בגרסה קודמת; לתחנות שנוספו השתמשו בקישורי המפה שברשימה':i===1?'ליוויס נוספה אחרי הפקת המפה, אינה מסומנת בה והמספרים שאחריה במפה נמוכים באחת מהרשימה':'המספרים תואמים לסדר התחנות'}</span>${link(dayRoutes[i],'פתיחת מסלול היום')}</figcaption></figure>`}<ol class="timeline">${d.stops.map((s,n)=>`<li><time>${s[0]}</time><div class="pin"></div><section><div><h3>${n+1}. ${s[1]}</h3><em>${s[3]}</em></div><p>${s[2]}</p>${link(s[4],'פתיחה במפה')}</section></li>`).join('')}</ol>${i===5?knife():''}<aside class="know"><b>כדאי לדעת</b><p>${d.note}</p></aside><div class="next">${i>0?`<a href="#d${i-1}">↑ היום הקודם</a>`:'<span></span>'}<a href="#home">למעלה</a>${i<6?`<a href="#d${i+1}">היום הבא ↓</a>`:'<span></span>'}</div></article>`}
function knife(){return `<section class="knife"><small>משימת הקנייה בקפבאשי</small><h3>סכין אחת, אחרי השוואה ביד</h3><p>מגיעים סביב 11:00, מחזיקים סכינים בכמה חנויות בלי לקנות, ורושמים דגם, פלדה, אורך ומחיר. רק אחרי ההשוואה חוזרים לקנייה אחת.</p><div class="brief"><b>מה לבקש</b><ul><li><strong>Gyuto באורך 200 מ״מ</strong>, לא 210 מ״מ, לשימוש ביתי בדגים ובשר.</li><li>השחזה דו־צדדית לימני, ידית יפנית wa ותחזוקה נמוכה.</li><li>עדיפות לפלדת אבקה אל־חלד SG2/R2. אם אין אחת שנוחה ביד, עוברים ל־VG10.</li><li>יעד טוב: עד כ־¥25,000. אפשר להגיע עד ₪1,000, אבל אין סיבה למצות את התקציב.</li></ul></div><div class="shops">${knifeShops.map((s,i)=>`<article><i>${i+1}</i><div><h4>${s.name}</h4><p><b>${s.hours}</b> · ${s.address}</p><small>${s.detail}</small>${link(s.map,'פתיחה במפה')}</div></article>`).join('')}</div><aside class="danger"><b>טיסה ו־tax-free</b><p>הסכין טסה רק במזוודה שנשלחת לבטן המטוס, לעולם לא בתיק היד. אורזים אותה קשיח. מ־1.11.2026 ההחזר ביפן נעשה בשדה: משלמים מחיר מלא, סורקים דרכון בעמדת ה־tax-free לפני מסירת המזוודה, ומשאירים את הסכין נגישה עד אחרי הסריקה. ירוק = סיימת; אדום = מציגים למכס.</p></aside><aside class="know"><b>שמירה על הלהב</b><p>לא חותכים עצמות, מזון קפוא או קליפות קשות. שוטפים ומייבשים מיד.</p></aside></section>`}
function gallery(){return `<section class="pagehead"><small>34 תחנות · 7 ימים</small><h1>האווירה של כל יום</h1><p>מבט חזותי נפרד על כל תחנה, כדי שהמסלול עצמו יישאר נקי וקל לסריקה.</p></section>${D.map((d,i)=>`<section class="gday"><header><div><small>${d.date}</small><h2>${d.area}</h2></div></header><div class="grid">${d.stops.map((s,n)=>`<article><figure><img loading="lazy" src="${IMG[dayPhotos[i][n]]||IMG['cover.png']}" alt="${esc(s[1])}"><i>${String(n+1).padStart(2,'0')}</i></figure><div><small>${s[0]}</small><h3>${link(s[4],s[1])}</h3><p>${s[2]}</p></div></article>`).join('')}</div></section>`).join('')}`}
function prep(){return `<section class="pagehead"><small>לפני שממריאים</small><h1>כרטיסים וכמה כללים</h1></section><section class="text"><h2>להזמין מראש</h2><div class="cards"><article><b>teamLab Planets</b><p>17.11 ב־11:00, סביב ¥3,800–4,200. לוודא שהכרטיס שביד תואם.</p></article></div><h2>תחבורה וקצב</h2><ul><li>הימים בנויים לפי אזורים. ברובם יש נסיעה אחת משיבויה ואז הליכה.</li><li>Suica או PASMO מספיקים לנסיעות העירוניות.</li><li>נובמבר נעים, אבל בערב קריר. שכבה קלה חשובה לתצפיות ולמפרץ.</li><li>גשם: מאריכים ב־Itoya, בתי קפה ווינטג׳ ומעבירים את הגנים לזמן יבש.</li><li>עוד וינטג׳: Koenji במקום הגן בשינג׳וקו, לא כתוספת לאותו יום.</li></ul></section>`}
const sourceLinks=[['המפה שלך','https://www.google.com/maps/d/viewer?mid=1U32_DRbjlrakZGMiXXO2_T2kAtn2tdg'],['גיליון המקומות וההמלצות','https://docs.google.com/spreadsheets/d/1nNcNSkgiWmu8BKOBjQgBGHGLJ5j6X8tt7E9hJvvHNQo/edit'],['Meiji Jingu','https://www.meijingu.or.jp/en/visit/'],['Nakano · GO TOKYO (כולל צילום Sun Mall)','https://www.gotokyo.org/en/destinations/western-tokyo/nakano/index.html'],['שעות Kama-asa','https://kama-asa.co.jp/en/pages/shops'],['שעות Tsubaya','https://tsubaya.jp/en/pages/businesshours'],['שעות Kamata','https://www.kap-kam.com/en/faq/'],['קפבאשי · כרבע פתוח בראשון','https://www.kappabashi.or.jp/en/qa/'],['עונת שלכת · GO TOKYO','https://www.gotokyo.org/en/story/guide/autumn-leaves-forecast/index.html'],['teamLab Planets','https://www.teamlab.art/e/planets/'],['JINS Shibuya והזמנה במקום','https://www.jins.com/jp/campaign/30minnightwalk/cities/shibuya/'],['זמני הכנת עדשות ב־JINS','https://faq-jp.jins.com/jp/faq/glasses/faq_detail.html?id=1692'],['Shinjuku Gyoen','https://policies.env.go.jp/national-garden/shinjukugyoen/english/guide/information/'],['Tsukiji','https://www.tsukiji.or.jp/english/'],['Sensō-ji ו־Kappabashi','https://www.japan-guide.com/e/e3004.html'],['הגנים המזרחיים של הארמון','https://kikuyou.or.jp/higashigyoen/en.html'],['Golden Gai','https://www.gotokyo.org/en/spot/62/index.html'],['Daikanyama T-Site','https://store.tsite.jp/daikanyama/english/'],['Ebisu Sushi Hatsume','https://ebisu-sushi-hatsume.com/en/'],['Bar TRENCH','https://small-axe.net/bar-trench/']];
function sources(){return `<section class="pagehead"><small>שקיפות</small><h1>מקורות וטריות</h1><p>שילבתי את המפה והגיליון שלך עם אתרים רשמיים ונקודות חובה בטוקיו.</p></section><section class="text source"><ul>${sourceLinks.map(x=>`<li>${link(x[1],x[0])}</li>`).join('')}</ul><aside class="know"><b>נבדק ב־21.9.2026</b><p>שעות, מחירים וימי סגירה יכולים להשתנות עד נובמבר. צילומי המקומות הורדו מ־Wikimedia Commons; רשימת הקרדיטים המלאה נמצאת בגרסה המקורית.</p></aside></section>`}
setView('days');
